دالة رتّب_تصاعديا(ق) {
    متغير ق_جديدة = اعكس(ق)
    رتب(ق_جديدة، دالة(أ، ب) { 
        إذا (أ > ب) {
            ارجع ١
        } 
        وإلا {
            ارجع ٠
        }
    })
    ارجع ق_جديدة
}
